test("codex rail display distinguishes loading, healthy, warning, and error states", () => {
  assert.deepEqual(getCodexStatusRailDisplay(codexStatus()), {
    tone: "loading",
    detail: "Checking Codex..."
  });
  assert.deepEqual(
    getCodexStatusRailDisplay(
      codexStatus({
        cliAvailable: true,
        cliVersion: "codex-cli 0.130.0",
        authenticated: true,
        message: "Codex is available."
      })
    ),
    {
      tone: "ok",
      detail: "codex-cli 0.130.0"
    }
  );
  assert.deepEqual(
    getCodexStatusRailDisplay(
      codexStatus({
        cliAvailable: true,
        cliVersion: "codex-cli 0.130.0",
        authenticated: false,
        message: "Codex CLI is available, but no Codex auth file or API key was found."
      })
    ),
    {
      tone: "warning",
      detail: "Codex CLI is available, but no Codex auth file or API key was found."
    }
  );
  assert.deepEqual(
    getCodexStatusRailDisplay(
      codexStatus({
        authenticated: false,
        message: "Codex CLI was not found in the SDK bundle or on PATH."
      })
    ),
    {
      tone: "error",
      detail: "Codex CLI was not found in the SDK bundle or on PATH."
    }
  );
});

